{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the availability of specific authentication options, which is verified by executing the login flow and observing the presented choices."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to enforce multi-factor or two-factor authentication at AAL2 is verified by attempting logins with valid and invalid factor combinations."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Periodic reauthentication behavior based on inactivity and overall timeouts is verified by simulating user sessions with specific idle and active durations."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of notifications upon account recovery is verified by triggering a recovery event and observing the delivery of the notification."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The distribution of notifications to registered addresses (excluding postal) is verified by triggering a notification event and checking the recipients."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The independence of the VBP session from the e-Devlet assertion validity window is verified by maintaining a VBP session after the e-Devlet assertion expires."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The content of the assertion request, specifically the inclusion of the VBP identifier and cryptographic nonce, is verified by inspecting the network traffic or code implementation."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion audience is verified by attempting to inject an assertion intended for a different relying party and observing the rejection."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The enforcement of the binding process for changing SMS phone numbers is verified by attempting to change the number without completing the required authentication steps."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to bind multiple authenticators is verified by adding more than one authenticator to a single account and confirming their coexistence."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The authentication level required for binding a new authenticator is verified by attempting to bind an authenticator at different AAL levels and observing the system's response."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of independent notifications upon adding an authenticator is verified by adding a new authenticator and checking for the notification via a separate channel."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of confirmation codes after use is verified by submitting a valid code, then attempting to resubmit the same code within its validity period."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of assertion signatures is verified by presenting an assertion with an invalid or tampered signature and observing the rejection."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "Replay protection is verified by submitting the same valid e-Devlet assertion twice and observing the rejection of the second attempt."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The initiation of federation transactions by VBP as the RP is verified by inspecting the sequence of network requests or the code logic for the federation flow."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of information leakage during proofing is verified by submitting incorrect self-asserted information and comparing the error messages or system behavior with correct submissions."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of core attributes against authoritative sources or signed evidence is verified by submitting test data that matches or does not match the source data."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of proofing notifications to validated addresses is verified by completing the IAL2 proofing process and checking for the notification at the specified address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of knowledge-based verification is verified by inspecting the code and configuration to ensure no such mechanism is implemented or enabled."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of email for out-of-band authentication is verified by inspecting the authentication logic and configuration to confirm email is not used for this purpose."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "The 5-minute validity window for SMS codes is verified by submitting a correct code after 5 minutes and observing the rejection, and before 5 minutes and observing success."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "The single-use nature of SMS codes is verified by submitting a valid code twice within its validity period and observing the rejection of the second attempt."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "The non-resetting of failed authentication counts upon generating a new SMS code is verified by failing authentication, requesting a new code, and checking the failure count."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "The absence of additional password composition requirements is verified by setting passwords that meet length and blocklist criteria but violate common composition rules (e.g., all lowercase)."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik sonlandırılmasının, sistem üzerinde süre ve koşul manipülasyonu yapılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediğinin, olaylar üretilip kayıtların incelenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC cinsinden ve belirlenen ayrıntı düzeyinde üretilip üretilmediğinin, sistem saatleri ve kayıtlar üzerinden gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin algılanıp algılanmadığının ve uyarıların gönderilip gönderilmediğinin, saldırı senaryoları çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Kimlik doğrulama bilgilerinin (parola, TOTP) ekranda gizlenip gizlenmediğinin, giriş ekranında girdi vererek ve ekran görüntüsü alarak gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolunca yeniden kimlik doğrulama zorunluluğunun, süre manipülasyonu ve işlem denemesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüklü olup olmadığının, ağ trafiği yakalanarak ve şifreleme protokollerinin çalışması gözlemlenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz girdilerin (bozuk veri, aşırı uzunluk, enjeksiyon denemeleri) reddedilip reddedilmediğinin, çeşitli girdilerle sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediğinin ve detaylı logların yetkili personele mi gösterildiğinin, hata senaryoları üretilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısının, taslak kaydının ve veri kaybı olmadan devam etmenin, süre manipülasyonu ve form doldurma akışıyla doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmadığının ve bot eşiği aşıldığında etkileşimsiz kanıt veya nesne tanıma sorgusunun devreye girdiğinin, bot simülasyonu ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edildiğinin ve belirsiz durumda bekleme modunda kalındığının, KÖA simülasyonu ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirtecinin sınırlı kipte oturum açtığının ve kişisel verinin gizlendiğinin, farklı belirteçlerle giriş yapılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulandığının, bildirimlerin ve sızıntı durumunda zorunlu değişikliğin, hesap senaryolarıyla doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edildiğinin ve tekrar kullanımın reddedildiğinin, zaman manipülasyonu ve kod denemeleriyle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiğinin doğrulayıcıyı devre dışı bıraktığının ve hesap kurtarma akışının, ardışık hatalı girişlerle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 ve AAL3 oturumlarında hareketsizlik sonrası farklı yeniden kimlik doğrulama akışlarının (parola vs. e-Devlet) ve oturum sırrı silinmesinin, senaryo çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşıldığında en eski oturumun sonlandırılıp bildirildiğinin ve SIEM'e iletimin, çoklu oturum açma senaryolarıyla doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut ve sayı sınırlarının uygulandığının ve ret mesajının içeriğinin, çeşitli dosyalar yükleyerek gözlemlenmesi gerekir."
    }
  ]
}

{
