    },
    {
      "requirement_id": "ETC-060",
      "methods": [
        "Test"
      ],
      "rationale": "The start conditions for the LOA speed timer in Level 1 and Level 2 are verified by receiving MAs and passing balises, then checking the timer start timestamps."
    },
    {
      "requirement_id": "ETC-061",
      "methods": [
        "Test"
      ],
      "rationale": "The conversion of LOA to EOA and deletion of information upon LOA speed timer timeout is verified by expiring the timer and observing the speed profile and stored data."
    },
    {
      "requirement_id": "ETC-062",
      "methods": [
        "Test"
      ],
      "rationale": "The start of the Overlap timer, including the handling of 'infinite' timeout values, is verified by passing the start location and checking the timer state."
    },
    {
      "requirement_id": "ETC-063",
      "methods": [
        "Test"
      ],
      "rationale": "The deletion of overlap and redetermination of Supervised Location upon Overlap timer timeout is verified by expiring the timer and observing the resulting state."
    },
    {
      "requirement_id": "ETC-064",
      "methods": [
        "Test"
      ],
      "rationale": "The treatment of the Overlap timer as expired upon train standstill is verified by stopping the train after the timer has started and observing the application of timeout consequences."
    },
    {
      "requirement_id": "ETC-065",
      "methods": [
        "Test"
      ],
      "rationale": "The immediate application of Overlap timeout consequences when a new MA with a rearward start location is received is verified by sending such an MA and observing the state change."
    },
    {
      "requirement_id": "ETC-066",
      "methods": [
