{
  "test_cases": [
    {
      "id": "TC-074-01",
      "title": "MA kısaltma isteğinin kabulü (tren sınırı gerisinde)",
      "covers": [
        "ETC-074"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU, geçerli bir MA ve ilgili mod profili ile SH alanı balise grubu listesine sahiptir. RBC ile iletişim kurulmuştur.",
      "test_inputs": "RBC'den gelen MA kısaltma isteği: Önerilen kısaltılmış MA'nın İndication supervision limit'i, trenin ön ucunun mevcut konumunun gerisinde olacak şekilde ayarlanır. İsteğe mod profili ve SH alanı balise grubu listesi eklenir.",
      "assumptions": "Trenin ön ucunun konumu, önerilen kısaltılmış MA'nın İndication supervision limit'inden geridedir.",
      "steps": [
        {
          "no": 1,
          "action": "RBC'den, trenin ön ucunun önerilen MA'nın İndication supervision limit'inden gerisinde olduğu bir MA kısaltma isteği gönderilir.",
          "expected": "OBU isteği kabul eder."
        },
        {
          "no": 2,
          "action": "OBU'nun aktif MA, mod profili ve SH alanı balise grubu listesi kontrol edilir.",
          "expected": "OBU, önerilen kısaltılmış MA'yı, ilgili mod profilini ve SH alanı balise grubu listesini yeni geçerli MA olarak kabul eder ve depolar."
        },
        {
          "no": 3,
          "action": "OBU'dan RBC'ye gönderilen mesaj kontrol edilir.",
          "expected": "OBU, RBC'ye isteğin kabul edildiğine dair kararını bildirir."
        }
      ]
    },
    {
      "id": "TC-074-02",
      "title": "MA kısaltma isteğinin reddi (tren sınırı ilerisinde)",
      "covers": [
        "ETC-074"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, geçerli bir MA ve ilgili mod profili ile SH alanı balise grubu listesine sahiptir. RBC ile iletişim kurulmuştur.",
      "test_inputs": "RBC'den gelen MA kısaltma isteği: Önerilen kısaltılmış MA'nın İndication supervision limit'i, trenin ön ucunun mevcut konumunun ilerisinde olacak şekilde ayarlanır. İsteğe mod profili ve SH alanı balise grubu listesi eklenir.",
      "assumptions": "Trenin ön ucunun konumu, önerilen kısaltılmış MA'nın İndication supervision limit'inden ileridedir.",
      "steps": [
        {
          "no": 1,
          "action": "RBC'den, trenin ön ucunun önerilen MA'nın İndication supervision limit'inden ilerisinde olduğu bir MA kısaltma isteği gönderilir.",
          "expected": "OBU isteği reddeder."
        },
        {
          "no": 2,
          "action": "OBU'nun aktif MA, mod profili ve SH alanı balise grubu listesi kontrol edilir.",
          "expected": "OBU, önceki MA'yı, mod profilini ve SH alanı balise grubu listesini geçerli olarak korur; önerilen yeni değerleri kabul etmez."
        },
        {
          "no": 3,
          "action": "OBU'dan RBC'ye gönderilen mesaj kontrol edilir.",
          "expected": "OBU, RBC'ye isteğin reddedildiğine dair kararını bildirir."
        }
      ]
    },
    {
      "id": "TC-074-03",
      "title": "MA kısaltma isteğinin kabulü (sınır durumu: tren sınırı tam üstünde)",
      "covers": [
        "ETC-074"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "OBU, geçerli bir MA'ya sahiptir. RBC ile iletişim kurulmuştur.",
      "test_inputs": "RBC'den gelen MA kısaltma isteği: Önerilen kısaltılmış MA'nın İndication supervision limit'i, trenin ön ucunun mevcut konumuyla tam olarak aynı konumda olacak şekilde ayarlanır.",
      "assumptions": "Gereksinim metninde 'in rear' (gerisinde) ifadesi kullanılmıştır. Sınır durumunda (tam üstünde) kabul edilebilirlik, sistemin 'in rear' tanımına göre belirlenir. Bu test, sınır davranışını doğrulamak için tasarlanmıştır. Varsayım: Sistem, 'in rear' koşulunu 'konum <= limit' olarak değerlendirir veya spesifik bir eşik kullanır. Bu test, sistemin bu sınırda tutarlı bir karar verdiğini ve RBC'yi bilgilendirdiğini doğrular. Not: Spesifik eşik değeri gereksinimde belirtilmediği için, test sistemin mevcut konfigürasyonuna göre davranışını gözlemlemeye yöneliktir. Ancak, tipik ERTMS uygulamalarında 'in rear' genellikle 'geriye doğru mesafe > 0' veya 'konum < limit' olarak yorumlanır. Eğer 'konum == limit' ise, bu 'in rear' değildir. Bu nedenle, bu test vaka, sistemin sınır davranışını (kabul veya ret) ve RBC'ye bildirim yapmasını doğrulamak içindir. Varsayım: Sistem, 'in rear' koşulunu 'tren konumu < limit' olarak değerlendirir. Bu durumda, 'konum == limit' isteği reddedilmelidir. Ancak, gereksinim 'in rear' derken 'geriye doğru' kastediyorsa, eşitlik durumu belirsizdir. Bu test, sistemin bu belirsiz sınırda tutarlı bir karar verdiğini ve RBC'ye bildirdiğini doğrulamak için kullanılır. Daha güvenli bir varsayım: 'in rear' = 'tren konumu < limit'. Bu durumda, 'konum == limit' isteği reddedilmelidir. Bu test vaka, bu varsayım altında reddedilme senaryosunu test eder. Alternatif olarak, 'in rear' = 'tren konumu <= limit' ise kabul edilir. Bu test, sistemin belirlenen eşik davranışını doğrulamak içindir. Varsayım: Sistem, 'in rear' koşulunu 'tren konumu < limit' olarak değerlendirir.",
      "steps": [
        {
          "no": 1,
          "action": "RBC'den, trenin ön ucunun önerilen MA'nın İndication supervision limit'iyle tam olarak aynı konumda olduğu bir MA kısaltma isteği gönderilir.",
          "expected": "OBU, sistemin 'in rear' tanımına göre bir karar verir (kabul veya ret). Bu test vaka, sistemin bu sınır durumunda tutarlı bir karar verdiğini doğrulamak içindir. Varsayım: 'in rear' = 'konum < limit' ise, istek reddedilir. 'in rear' = 'konum <= limit' ise, istek kabul edilir. Test, sistemin mevcut konfigürasyonuna göre davranışını gözlemlemeye yöneliktir."
        },
        {
          "no": 2,
          "action": "OBU'nun aktif MA durumu kontrol edilir.",
          "expected": "OBU, aldığı karara göre MA'yı günceller veya korur."
        },
        {
          "no": 3,
          "action": "OBU'dan RBC'ye gönderilen mesaj kontrol edilir.",
          "expected": "OBU, RBC'ye aldığı karara (kabul veya ret) dair bildirim yapar."
        }
      ]
    }
  ]
}

