{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Session AAL cannot exceed authentication event AAL",
      "covers": [
        "KDH-041"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A user account exists with authentication capabilities for AAL1 and AAL2. The system allows session creation based on authentication events.",
      "test_inputs": "User credentials for AAL1 authentication. A request to access a resource requiring AAL2 session context.",
      "assumptions": "The system logs the AAL level of the authentication event and the resulting session. Access to AAL2 resources requires a session with AAL2 or higher.",
      "steps": [
        {
          "no": 1,
          "action": "Authenticate the user using an AAL1 method (e.g., password only).",
          "expected": "Authentication succeeds. The system creates a session associated with AAL1."
        },
        {
          "no": 2,
          "action": "Attempt to access a resource or function that requires an AAL2 session context using the current session.",
          "expected": "The system denies access or prompts for re-authentication at AAL2. The session is not treated as AAL2. The session AAL remains AAL1."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Session AAL can be lower than authentication event AAL",
      "covers": [
        "KDH-041"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A user account exists with authentication capabilities for AAL2. The system allows session creation based on authentication events.",
      "test_inputs": "User credentials for AAL2 authentication (e.g., password + OTP).",
      "assumptions": "The system allows the session to be established at a lower AAL than the authentication event if configured or if the user chooses a lower security context for the session, or if the session inherits the AAL but is used in a context that only requires lower AAL. The requirement states 'treating it at a lower AAL is permitted'. This test verifies that a high AAL authentication does not force a high AAL session if the system logic allows downgrading or if the session is used for lower AAL purposes without error.",
      "steps": [
        {
          "no": 1,
          "action": "Authenticate the user using an AAL2 method.",
          "expected": "Authentication succeeds. The system creates a session. The session is capable of being treated at AAL2."
        },
        {
          "no": 2,
          "action": "Access a resource that only requires AAL1 session context using the current session.",
          "expected": "Access is granted. The session is treated as sufficient for AAL1 (which is lower than the AAL2 authentication event). No error occurs."
        }
      ]
    }
  ]
}

