{
  "test_cases": [
    {
      "id": "TC-KDH-038-01",
      "title": "Multiple authenticators disabled upon reaching failure threshold",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with both password and a second factor (e.g., OTP) enabled. The failure threshold is defined in VBP SDD §14 (assumed to be 5 for this test).",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for consecutive failed attempts is 5, as per VBP SDD §14. The system tracks failures per authenticator and per account.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the correct username, an incorrect password, and an incorrect second factor code.",
          "expected": "Authentication fails. The system records a failed attempt for both the password and the second factor authenticators."
        },
        {
          "no": 2,
          "action": "Repeat the login attempt with incorrect credentials for the remaining number of attempts required to reach the threshold (e.g., 4 more times if threshold is 5).",
          "expected": "Each attempt fails. The system continues to record failures for both authenticators."
        },
        {
          "no": 3,
          "action": "Check the status of the password and second factor authenticators for the account.",
          "expected": "Both the password and the second factor authenticators are disabled for the account, as specified in NIST SP 800-63B-4 §3.2.2."
        }
      ]
    },
    {
      "id": "TC-KDH-038-02",
      "title": "Single authenticator failure does not disable other authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists with both password and a second factor enabled. The failure threshold is 5.",
      "test_inputs": "Valid username, incorrect password, correct second factor code.",
      "assumptions": "The system only disables authenticators involved in the failed attempts. If only the password is wrong, only the password authenticator is considered for the failure count.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the correct username, an incorrect password, and a correct second factor code.",
          "expected": "Authentication fails due to the incorrect password. The system records a failed attempt for the password authenticator only."
        },
        {
          "no": 2,
          "action": "Repeat the login attempt with an incorrect password and correct second factor code until the threshold is reached.",
          "expected": "Each attempt fails. The system records failures for the password authenticator."
        },
        {
          "no": 3,
          "action": "Check the status of the password and second factor authenticators for the account.",
          "expected": "The password authenticator is disabled. The second factor authenticator remains enabled, as it was not involved in the failed attempts (or its failure count did not reach the threshold independently)."
        }
      ]
    },
    {
      "id": "TC-KDH-038-03",
      "title": "Rebinding required after disabling multiple authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account has had both password and second factor disabled due to reaching the failure threshold.",
      "test_inputs": "Account recovery credentials or admin access to re-enable authenticators.",
      "assumptions": "The system requires re-binding of disabled authenticators before they can be used again, as per NIST SP 800-63B-4 §4.1.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to re-enable the password authenticator without completing the re-binding process.",
          "expected": "The system prevents the use of the password authenticator until the re-binding process is completed."
        },
        {
          "no": 2,
          "action": "Complete the re-binding process for the password authenticator.",
          "expected": "The password authenticator is re-enabled and can be used for authentication."
        },
        {
          "no": 3,
          "action": "Attempt to re-enable the second factor authenticator without completing the re-binding process.",
          "expected": "The system prevents the use of the second factor authenticator until the re-binding process is completed."
        },
        {
          "no": 4,
          "action": "Complete the re-binding process for the second factor authenticator.",
          "expected": "The second factor authenticator is re-enabled and can be used for authentication."
        }
      ]
    }
  ]
}

